parameters.query:
select id, source, message_id, sender_name, sender_email, sender_phone, subject, body, form_fields,
       to_char(received_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') as received_at, is_test
  from enquiries where id = $1::uuid;

