const POUND = /£\s?(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d{2}))?/g;

function poundAmounts(text) {
  return [...String(text ?? "").matchAll(POUND)].map((m) => Number(m[1].replace(/,/g, "")) + (m[2] ? Number(m[2]) / 100 : 0));
